import fortis.host { Console }
try func parse(s: String) Int => s as Int or fail
try func main(console: Console) {
  let f = parse
  let v = f("3") or fail
  let n: Outcome[Int] = f("4")
  let w = n or fail
  console.print("${v} ${w}")
}

import fortis.host { Console }
try func parse(s: String) Int => s as Int or fail
try func main(console: Console) {
  let f: try fn(String) Int = parse
  let g = try fn(s: String) Int => s as Int or fail
  let a = f("3") or fail
  let b = g("4") or fail
  let c = parse("5") or fail
  console.print("${a} ${b} ${c}")
}

import fortis.host { Console }
async func value() Int => 3
async try func parse(s: String) Int => s as Int or fail
async try func main(console: Console) {
  let f = value
  let pending: Future[Int] = f()
  let a = await pending
  let g = parse
  let pendingTry: Future[Outcome[Int]] = g("4")
  let b = await pendingTry or fail
  console.print("${a} ${b}")
}

